entries[21217] = { ["name"] = "Weisenfisch Supreme", ["text"] = "Benötigt Stufe 30\nBenutzen: Stellt im Verlauf von 21 Sek. 840.0 Gesundheit und 1260 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und regeneriert 15 Min. lang alle 5 Sekunden 6 Mana.\nVerkaufspreis:" }
entries[21218] = { ["name"] = "Blauer Qirajiresonanzkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\nBenötigt Reiten (75)\nBenutzen: Stößt ein Hochfrequenzsignal aus, das eine Qirajipanzerdrohne dazu zwingt, sich aus dem Boden unter dem Tempel von Ahn'Qiraj an die Oberfläche zu graben. Der Silithide gehorcht seinem Beschwörer und kann innerhalb des Tempels von Ahn'Qiraj als Reittier benutzt werden. Jegliche feindseligen Handlungen gegen den Reiter zwingen die Qirajipanzerdrohne, sich wieder einzugraben. (3 Sek. Abklingzeit)" }
entries[21219] = { ["name"] = "Rezept: Weisenfisch Supreme", ["text"] = "Benötigt Kochkunst (175)\nBenutzen: Lehrt Euch, wie man Weisenfisch Surpreme zubereitet.\nVerkaufspreis:\nWeisenfisch Supreme\nBenötigt Stufe 30\nBenutzen: Stellt im Verlauf von 21 Sek. 840.0 Gesundheit und 1260 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und regeneriert 15 Min. lang alle 5 Sekunden 6 Mana.\nVerkaufspreis:\nBenötigt Roher großer Weisenfisch , Scharfe Gewürze" }
