entries[21272] = { ["name"] = "Gesegnete Qirajimuskete", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDistanz Schusswaffe\n103 - 192 Schaden Tempo 2.60\n(56.73 Schaden pro Sekunde)\n+10 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\nAnlegen: Erhöht die Distanzangriffskraft um 31.\n\"Diese Waffe wurde mit Elementium erfüllt und verstärkt.\"\nVerkaufspreis:" }
entries[21273] = { ["name"] = "Gesegneter Akolythenstab der Qiraji", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n132 - 227 Schaden Tempo 3.00\n(59.83 Schaden pro Sekunde)\n+32 Ausdauer\n+33 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 76.\nAnlegen: Erhöht Eure Zaubertrefferwertung um 16.\nAnlegen: Erhöht Eure kritische Zaubertrefferwertung um 14.\n\"Diese Waffe wurde mit Elementium erfüllt und verstärkt.\"\nVerkaufspreis:" }
entries[21275] = { ["name"] = "Gesegneter Weissagungsstab der Qiraji", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n132 - 227 Schaden Tempo 3.00\n(59.83 Schaden pro Sekunde)\n+23 Ausdauer\n+24 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 143 und den verursachten Schaden um bis zu 48.\nAnlegen: Stellt alle 5 Sek. 15 Mana wieder her.\n\"Diese Waffe wurde mit Elementium erfüllt und verstärkt.\"\nVerkaufspreis:" }
entries[21277] = { ["name"] = "Ruhiger mechanischer Yeti", ["text"] = "Wird bei Benutzung gebunden\nBenutzen: Mit Rechtsklick Euren ruhigen mechanischen Yeti beschwören und freigeben.\nVerkaufspreis:" }
entries[21278] = { ["name"] = "Sturmschleierhandschuhe", ["text"] = "Wird beim Anlegen gebunden\nHände Leder\n99 Rüstung\nHaltbarkeit 35 / 35\nBenötigt Stufe 50\nAnlegen: Erhöht die Trefferwertung um 10.\nAnlegen: Erhöht die kritische Trefferwertung um 19.\n\nSturmschleier (0/4)\nSturmschleierrüstung\nSturmschleierhose\nSturmschleierschultern\nSturmschleierhandschuhe\n(2) Set : Chance von 5%, bei erfolgreichem Nahkampfangriff 15 bis 25 Naturschaden zuzufügen. (Procchance: 5%)\n(3) Set : Eine Chance von 2% bei Nahkampfangriffen 30 Energie wiederherzustellen. (Procchance: 2%)\n(4) Set : Erhöht die Angriffskraft um 14.\nVerkaufspreis:" }
entries[21279] = { ["name"] = "Foliant des Feuerballs XII", ["text"] = "Klassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt 'Feuerball' (Rang 12).\nSchleudert eine glühende Kugel hinaus, die 611 bis 776 Feuerschaden sowie 8 Sek. lang insgesamt 76 zusätzlichen Feuerschaden verursacht.\nVerkaufspreis:" }
entries[21280] = { ["name"] = "Foliant der arkanen Geschosse VIII", ["text"] = "Klassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt 'Arkane Geschosse' (Rang 8).\nSchleudert arkane Geschosse auf den Feind und verursacht 5 Sek. lang alle 1 Sek. 234 Arkanschaden.\nVerkaufspreis:" }
entries[21281] = { ["name"] = "Zauberfoliant des Schattenblitzes X", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 60\nBenutzen: Lehrt 'Schattenblitz' (Rang 10).\nSendet einen schattigen Blitz zum Gegner, der 497 bis 554 Schattenschaden verursacht.\nVerkaufspreis:" }
entries[21282] = { ["name"] = "Zauberfoliant des Feuerbrandes VIII", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 60\nBenutzen: Lehrt 'Feuerbrand' (Rang 8).\nVerbrennt den Feind und fügt 299 Feuerschaden sowie 15 Sek. lang insgesamt 510 zusätzlichen Feuerschaden zu.\nVerkaufspreis:" }
entries[21283] = { ["name"] = "Zauberfoliant der Verderbnis VII", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 60\nBenutzen: Lehrt 'Verderbnis' (Rang 7).\nVerdirbt das Ziel und verursacht 18 Sek. lang insgesamt 822 Schattenschaden.\nVerkaufspreis:" }
entries[21284] = { ["name"] = "Kodex der großen Heilung V", ["text"] = "Klassen: Priester\nBenötigt Stufe 60\nBenutzen: Lehrt 'Große Heilung' (Rang 5).\nEin langsam zu wirkender Zauber, der ein einzelnes Ziel um 2006 bis 2235 heilt.\nVerkaufspreis:" }
entries[21285] = { ["name"] = "Kodex der Erneuerung X", ["text"] = "Klassen: Priester\nBenötigt Stufe 60\nBenutzen: Lehrt 'Erneuerung' (Rang 10).\nHeilt das Ziel 15 Sek. lang um insgesamt 970.\nVerkaufspreis:" }
entries[21287] = { ["name"] = "Kodex des Gebets der Heilung V", ["text"] = "Klassen: Priester\nBenötigt Stufe 60\nBenutzen: Lehrt 'Gebet der Heilung' (Rang 5).\nEin wirkungsvolles Gebet heilt alle Gruppenmitglieder in einem Umkreis von 30 Metern um 1019 bis 1076.\nVerkaufspreis:" }
entries[21288] = { ["name"] = "Buchband: Segen der Weisheit VI", ["text"] = "Klassen: Paladin\nBenötigt Stufe 60\nBenutzen: Lehrt 'Segen der Weisheit' (Rang 6).\nBelegt ein befreundetes Ziel mit einem Segen und stellt 10 Min. lang alle 5 Sek. 33 Mana wieder her. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein.\nVerkaufspreis:" }
entries[21289] = { ["name"] = "Buchband: Segen der Macht VII", ["text"] = "Klassen: Paladin\nBenötigt Stufe 60\nBenutzen: Lehrt 'Segen der Macht' (Rang 7).\nBelegt ein befreundetes Ziel mit einem Segen und erhöht 10 Min. lang die Angriffskraft um 185. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein.\nVerkaufspreis:" }
entries[21290] = { ["name"] = "Buchband: Heiliges Licht IX", ["text"] = "Klassen: Paladin\nBenötigt Stufe 60\nBenutzen: Lehrt 'Heiliges Licht' (Rang 9).\nHeilt ein befreundetes Ziel um 1619 bis 1799.\nVerkaufspreis:" }
entries[21291] = { ["name"] = "Schrifttafel der Welle der Heilung X", ["text"] = "Klassen: Schamane\nBenötigt Stufe 60\nBenutzen: Lehrt 'Welle der Heilung' (Rang 10).\nHeilt ein befreundetes Ziel um 1647 bis 1878.\nVerkaufspreis:" }
entries[21292] = { ["name"] = "Schrifttafel des Totems der Erdstärke V", ["text"] = "Klassen: Schamane\nBenötigt Stufe 60\nBenutzen: Lehrt 'Totem der Erdstärke' (Rang 5).\nBeschwört ein Totem der Erdstärke mit 5 Gesundheit zu Füßen des Zaubernden. Das Totem erhöht die Stärke der Gruppenmitglieder in einem Umkreis von 20 Metern um 77. Hält 2 Min. lang an.\nVerkaufspreis:" }
entries[21293] = { ["name"] = "Schrifttafel des Totems der luftgleichen Anmut III", ["text"] = "Klassen: Schamane\nBenötigt Stufe 60\nBenutzen: Lehrt 'Totem der luftgleichen Anmut' (Rang 3).\nBeschwört ein Totem der luftgleichen Anmut mit 5 Gesundheit zu Füßen des Zaubernden. Das Totem erhöht die Beweglichkeit der Gruppenmitglieder in einem Umkreis von 20 Metern um 77. Hält 2 Min. lang an.\nVerkaufspreis:" }
entries[21294] = { ["name"] = "Buch der heilenden Berührung XI", ["text"] = "Klassen: Druide\nBenötigt Stufe 60\nBenutzen: Lehrt 'Heilende Berührung' (Rang 11).\nHeilt ein befreundetes Ziel um 2303 bis 2714.\nVerkaufspreis:" }
entries[21295] = { ["name"] = "Buch des Sternenfeuers VII", ["text"] = "Klassen: Druide\nBenötigt Stufe 60\nBenutzen: Lehrt 'Sternenfeuer' (Rang 7).\nVerursacht 514 bis 603 Arkanschaden am Ziel.\nVerkaufspreis:" }
entries[21296] = { ["name"] = "Buch der Verjüngung XI", ["text"] = "Klassen: Druide\nBenötigt Stufe 60\nBenutzen: Lehrt 'Verjüngung' (Rang 11).\nHeilt beim Ziel 12 Sek. lang insgesamt 888 Schaden.\nVerkaufspreis:" }
entries[21297] = { ["name"] = "Handbuch des heldenhaften Stoßes IX", ["text"] = "Klassen: Krieger\nBenötigt Stufe 60\nBenutzen: Lehrt 'Heldenhafter Stoß' (Rang 9).\nEin heftiger Angriff, der den Nahkampfschaden um 157 erhöht und ein hohes Maß an Bedrohung erzeugt.\nVerkaufspreis:" }
entries[21298] = { ["name"] = "Handbuch des Schlachtrufs VII", ["text"] = "Klassen: Krieger\nBenötigt Stufe 60\nBenutzen: Lehrt 'Schlachtruf' (Rang 7).\nDer Krieger schreit, wodurch sich die Nahkampfangriffskraft der Gruppe innerhalb eines Radius von 20 Metern um 240 erhöht. Hält 2 Min. lang an.\nVerkaufspreis:" }
entries[21299] = { ["name"] = "Handbuch der Rache VI", ["text"] = "Klassen: Krieger\nBenötigt Stufe 60\nBenutzen: Lehrt 'Rache' (Rang 6).\nFührt einen sofortigen Gegenangriff gegen den Feind aus, der 342 bis 418 Schaden verursacht und dabei ein hohes Maß an Bedrohung generiert. 'Rache' muss auf Blocken, Ausweichen oder Parieren folgen.\nVerkaufspreis:" }
entries[21300] = { ["name"] = "Leitfaden des Meuchelns IX", ["text"] = "Klassen: Schurke\nBenötigt Stufe 60\nBenutzen: Lehrt 'Meucheln' (Rang 9).\nDas Ziel meucheln und ihm 150% Waffenschaden plus 225 zufügen. Muss hinter dem Ziel sein. In der Waffenhand muss sich ein Dolch befinden. Gewährt 1 Combopunkt.\nVerkaufspreis:" }
entries[21301] = { ["name"] = "Grüne Helferbox", ["text"] = "Wird bei Benutzung gebunden\nBenutzen: Mit Rechtsklick Euren Helfer beschwören und freigeben. Erfordert einen Schneeball zur Beschwörung." }
entries[21302] = { ["name"] = "Leitfaden des tödlichen Gifts V", ["text"] = "Klassen: Schurke\nBenötigt Stufe 60\nBenutzen: Lehrt 'Tödliches Gift' (Rang 5).\nÜberzieht eine Waffe mit Gift, das eine Stunde lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner 12 Sek. lang zu vergiften und ihm 136 Naturschaden zuzufügen. Kann bis zu 5-mal auf ein einzelnes Ziel angewendet werden.\nVerkaufspreis:\nTödliches Gift V\nKlassen: Schurke\nBenötigt Stufe 60\nBenutzen: Überzieht eine Waffe mit Gift, das eine Stunde lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner 12 Sek. lang zu vergiften und ihm 136 Naturschaden zuzufügen. Kann bis zu 5-mal auf ein einzelnes Ziel angewendet werden. (Procchance: 30%)\nVerkaufspreis:\nBenötigt Todeskraut (2), Kristallphiole" }
entries[21303] = { ["name"] = "Leitfaden der Finte V", ["text"] = "Klassen: Schurke\nBenötigt Stufe 60\nBenutzen: Lehrt 'Finte' (Rang 5).\nEin Täuschungsmanöver wird durchgeführt, das zwar keinen Schaden verursacht, aber Eure Bedrohung um ein großes Maß verringert und die Wahrscheinlichkeit senkt, dass der Feind Euch angreift.\nVerkaufspreis:" }
entries[21304] = { ["name"] = "Lehrbuch: Mehrfachschuss V", ["text"] = "Klassen: Jäger\nBenötigt Stufe 60\nBenutzen: Lehrt 'Mehrfachschuss' (Rang 5).\nFeuert mehrere Geschosse ab, trifft 3 Ziele und fügt zusätzliche 150 Schaden zu.\nVerkaufspreis:" }
entries[21305] = { ["name"] = "Rote Helferbox", ["text"] = "Wird bei Benutzung gebunden\nBenutzen: Mit Rechtsklick Euren Helfer beschwören und freigeben. Erfordert einen Schneeball zur Beschwörung." }
entries[21306] = { ["name"] = "Lehrbuch: Schlangenbiss IX", ["text"] = "Klassen: Jäger\nBenötigt Stufe 60\nBenutzen: Lehrt 'Schlangenbiss' (Rang 9).\nBeißt das Ziel und verursacht 15 Sek. lang (Fernkampfangriffskraft * 0.1 + 111 * 5) Naturschaden. Es kann immer nur ein Biss oder Stich pro Jäger auf einem einzelnen Ziel aktiv sein.\nVerkaufspreis:" }
entries[21307] = { ["name"] = "Lehrbuch: Aspekt des Falken VII", ["text"] = "Klassen: Jäger\nBenötigt Stufe 60\nBenutzen: Lehrt Aspekt des Falken (Rang 7).\nDer Jäger nimmt die Aspekte eines Falken an: Die Distanzangriffskraft wird um 120 erhöht. Es kann immer nur jeweils ein Aspekt aktiv sein.\nVerkaufspreis:" }
entries[21308] = { ["name"] = "Bimmelglöckchen", ["text"] = "Wird bei Benutzung gebunden\nBenutzen: Mit Rechtsklick Euer Rentier beschwören und freigeben. Erfordert einen Schneeball zur Beschwörung." }
