entries[21952] = { ["name"] = "Vorlage: Smaragdkrone der Zerstörung", ["text"] = "Benötigt Juwelenschleifen (275)\nBenutzen: Lehrt Euch die Herstellung einer Smaragdkrone der Zerstörung.\nVerkaufspreis:\nSmaragdkrone der Zerstörung\nWird beim Anlegen gebunden\nKopf Stoff\n64 Rüstung\nHaltbarkeit 50 / 50\nBenötigt Stufe 50\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 30.\nAnlegen: Erhöht Eure kritische Zaubertrefferwertung um 14.\nVerkaufspreis:\nBenötigt Gewaltiger Smaragd (2), Großer Opal (2), Blauer Saphir (2), Arkanitbarren (2), Thoriumbarren (2)" }
entries[21953] = { ["name"] = "Vorlage: Smaragdeule", ["text"] = "Benötigt Juwelenschleifen (285)\nBenutzen: Lehrt Euch die Herstellung einer Smaragdeule.\nVerkaufspreis:\nFigur - Smaragdeule\nWird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\nBenötigt Juwelenschleifen (285)\nAnlegen: Stellt alle 5 Sek. 2 Mana wieder her.\nBenutzen: Stellt 12 Sek. lang pro Sekunde 60 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Gewaltiger Smaragd (2), Arkanitbarren (2), Thoriumbarren (2), Mächtiges Mojo (4)" }
