entries[21955] = { ["name"] = "Vorlage: Schwarzer Diamantkrebs", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (300)\nBenutzen: Lehrt Euch die Herstellung eines schwarzen Diamantkrebses.\n\nFigur - Schwarzer Diamantkrebs\nWird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 55\nBenötigt Juwelenschleifen (300)\nAnlegen: Erhöht Verteidigungswertung um 9.\nBenutzen: Verringert 20 Sek. lang den erlittenen Nahkampfschaden um 35. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Makelloser schwarzer Diamant (4), Schwarzer Diamant (4), Azerothischer Diamant (2), Arkanitbarren (2), Thoriumbarren (4)" }
