entries[22221] = { ["name"] = "Pläne: Obsidianpanzertunika", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (300)\nBenötigt Zirkel des Cenarius\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung einer Obsidianpanzertunika.\nVerkaufspreis:\nObsidianpanzertunika\nWird beim Anlegen gebunden\nBrust Kette\n523 Rüstung\nHaltbarkeit 140 / 140\nBenötigt Stufe 60\nAnlegen: Erhöht die Angriffskraft um 76.\nAnlegen: Erhöht Eure kritische Trefferwertung um 14.\nAnlegen: Der erlittene Zauberschaden wird um 10 verringert.\nVerkaufspreis:\nBenötigt Großer Obsidiansplitter (15), Kleiner Obsidiansplitter (36), Verzaubertes Leder (12), Wächterstein (10), Azerothischer Diamant (4)" }
entries[22222] = { ["name"] = "Pläne: Dicke Obsidianbrustplatte", ["text"] = "Benötigt Schmiedekunst (300)\nBenutzen: Lehrt Euch die Herstellung einer dicken Obsidianbrustplatte.\nVerkaufspreis:\nDicke Obsidianbrustplatte\nWird beim Anlegen gebunden\nBrust Platte\n929 Rüstung\n+38 Stärke\n+16 Ausdauer\nHaltbarkeit 165 / 165\nBenötigt Stufe 60\nAnlegen: Bei einem Treffer durch einen Schadenszauber, der keinen regelmäßigem Schaden zufügt, besteht eine Chance von 30%, 6 Sek. lang einen Zauberschild zu aktivieren, der 300 bis 500 Schaden der entsprechenden Schadenskategorie absorbiert. (Procchance: 30%, 10s Abklingzeit)\nVerkaufspreis:\nBenötigt Großer Obsidiansplitter (18), Kleiner Obsidiansplitter (40), Verzauberter Thoriumbarren (12), Essenz der Erde (10), Gewaltiger Smaragd (4)" }
